def solve_all():
    max_s = 0
    best_frac = (0, 1)
    for n in range(1, 13):
        x = 12 + n
        y = 13 - n
        for q in range(y + 1, x * y + y + 2):
            p = (x * q) // (q - y) + 1
            if p > x:
                s_num = x * q + y * p
                s_den = p * q
